def evaluate(current_reputation, observation, my_history, round_num):
    # Asymmetric reputation update: donating gives +0.5, not donating gives -0.35
    if observation["action"] == "donate":
        delta = 0.5
    else:
        delta = -0.35
    # Reduce update magnitude when reputation is very high or very low
    if current_reputation > 0.8:
        delta *= 0.6
    elif current_reputation < -0.8:
        delta *= 0.6
    # Add a small decay toward zero to prevent runaway reputation
    decay = 0.02 * (0 - current_reputation)  # pulls slightly toward zero
    new_reputation = current_reputation + delta + decay
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Determine habit based on own recent donations (last 3 rounds)
    if my_history:
        recent_actions = [entry['action'] for entry in my_history[-3:]]
        recent_donations = sum(1 for a in recent_actions if a == 'donate')
        # If majority of recent actions were donations, lower threshold
        threshold = 0.6 if recent_donations >= 2 else 0.8
    else:
        threshold = 0.8  # default early threshold
    return recipient_reputation > threshold

